declare(strict_types=1);session_start();require __DIR__.'/bootstrap.php';
$pass=(string)($CFG['admin_password']??'');
if(isset($_POST['logout'])){session_destroy();header('Location: leads.php');exit;}
if(empty($_SESSION['rccg_admin'])){
  $err='';if($_SERVER['REQUEST_METHOD']==='POST'){if($pass!=='' && !hash_equals($pass,(string)($_POST['password']??''))){$err='Incorrect password.';}elseif($pass==='CHANGE-ME-NOW'||$pass===''){$err='Set a strong admin_password in rccg_fife_private/config.php first.';}else{$_SESSION['rccg_admin']=1;header('Location: leads.php');exit;}}
  ?><!doctype html><meta name="viewport" content="width=device-width"><title>RCCG Admin</title><style>body{font:16px system-ui;background:#f6f8fb;margin:0;padding:24px}.box{max-width:420px;margin:10vh auto;background:white;padding:24px;border-radius:18px;box-shadow:0 12px 34px #0001}input,button{width:100%;padding:12px;margin-top:10px;border-radius:10px;border:1px solid #d8e0ec}button{background:#0a4dbf;color:white;font-weight:800}</style><div class="box"><h1>RCCG Open Heavens Fife Admin</h1><p>Enter the admin password.</p><?php if($err):?><p style="color:#b42318"><?=htmlspecialchars($err)?></p><?php endif?><form method="post"><input type="password" name="password" required><button>Sign in</button></form></div><?php exit;
}
$csrf=$_SESSION['csrf']??=bin2hex(random_bytes(16));
function require_csrf():void{if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))die('Invalid request.');}
$flash='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['action'])){require_csrf();$a=$_POST['action'];
  if($a==='save_setting'){$DB->prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value')->execute([(string)$_POST['key'],(string)$_POST['value']]);$flash='Setting saved.';}
  elseif($a==='add_service'){$DB->prepare('INSERT INTO service_times(sort_order,day_label,time_label,service_name,note) VALUES(?,?,?,?,?)')->execute([(int)$_POST['sort_order'],trim((string)$_POST['day_label']),trim((string)$_POST['time_label']),trim((string)$_POST['service_name']),trim((string)$_POST['note'])]);$flash='Service time added.';}
  elseif($a==='save_recurring'){$stmt=$DB->prepare('UPDATE recurring_events SET title=?,schedule_label=?,weekdays=?,start_time=?,end_time=?,description=?,location_text=?,join_url=?,active=? WHERE id=?');$stmt->execute([trim((string)$_POST['title']),trim((string)$_POST['schedule_label']),trim((string)$_POST['weekdays']),trim((string)$_POST['start_time']),trim((string)$_POST['end_time']),trim((string)$_POST['description']),trim((string)$_POST['location_text']),trim((string)$_POST['join_url']),isset($_POST['active'])?1:0,(int)$_POST['id']]);$flash='Recurring schedule saved.';}
  elseif($a==='delete_service'){$DB->prepare('DELETE FROM service_times WHERE id=?')->execute([(int)$_POST['id']]);$flash='Service time deleted.';}
  elseif($a==='add_event'){$DB->prepare('INSERT INTO events(title,start_at,end_at,description,location,join_url,featured,active) VALUES(?,?,?,?,?,?,?,1)')->execute([trim((string)$_POST['title']),trim((string)$_POST['start_at']),trim((string)$_POST['end_at']),trim((string)$_POST['description']),trim((string)$_POST['location']),trim((string)$_POST['join_url']),isset($_POST['featured'])?1:0]);$flash='Event added.';}
  elseif($a==='delete_event'){$DB->prepare('DELETE FROM events WHERE id=?')->execute([(int)$_POST['id']]);$flash='Event deleted.';}
  elseif($a==='add_ref'){$DB->prepare('INSERT INTO donation_refs(label,reference_code,sort_order) VALUES(?,?,?)')->execute([trim((string)$_POST['label']),strtoupper(trim((string)$_POST['reference_code'])),(int)$_POST['sort_order']]);$flash='Donation reference added.';}
  elseif($a==='delete_ref'){$DB->prepare('DELETE FROM donation_refs WHERE id=?')->execute([(int)$_POST['id']]);$flash='Donation reference deleted.';}
  elseif($a==='delete_contact'){$DB->prepare('DELETE FROM contacts WHERE id=?')->execute([(int)$_POST['id']]);$flash='Message deleted.';}
  elseif($a==='delete_subscriber'){$DB->prepare('DELETE FROM subscribers WHERE id=?')->execute([(int)$_POST['id']]);$flash='Subscriber deleted.';}
  elseif($a==='delete_worshipper'){$DB->prepare('DELETE FROM first_time_worshippers WHERE id=?')->execute([(int)$_POST['id']]);$flash='First-time worshipper response deleted.';}
}
if(($_GET['export']??'')==='worshippers'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="rccg-first-time-worshippers.csv"');$o=fopen('php://output','w');fputcsv($o,['created_at','name','email','phone','address','rating','may_contact','prayer_point','suggestion']);foreach($DB->query("SELECT created_at,name,email,phone,address,rating,may_contact,prayer_point,suggestion FROM first_time_worshippers ORDER BY id DESC") as $r){$r['may_contact']=$r['may_contact']?'Yes':'No';fputcsv($o,$r);}fclose($o);exit;}
if(($_GET['export']??'')==='verified'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="rccg-verified-subscribers.csv"');$o=fopen('php://output','w');fputcsv($o,['email','verified_at','page']);foreach($DB->query("SELECT email,verified_at,page FROM subscribers WHERE verified_at IS NOT NULL ORDER BY verified_at DESC") as $r)fputcsv($o,$r);fclose($o);exit;}
