$hasRecurring=(bool)$DB->query("SELECT 1 FROM sqlite_master WHERE type='table' AND name='recurring_events'")->fetchColumn();
$DB->exec("CREATE TABLE IF NOT EXISTS first_time_worshippers (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',prayer_point TEXT NOT NULL DEFAULT '',rating INTEGER NOT NULL,suggestion TEXT NOT NULL DEFAULT '',may_contact INTEGER NOT NULL DEFAULT 0,page TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,ip_hash TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'new')");
$counts=['subscribers'=>(int)$DB->query('SELECT COUNT(*) FROM subscribers')->fetchColumn(),'verified'=>(int)$DB->query('SELECT COUNT(*) FROM subscribers WHERE verified_at IS NOT NULL')->fetchColumn(),'messages'=>(int)$DB->query('SELECT COUNT(*) FROM contacts')->fetchColumn(),'first-time worshippers'=>(int)$DB->query('SELECT COUNT(*) FROM first_time_worshippers')->fetchColumn(),'events'=>(int)$DB->query('SELECT COUNT(*) FROM events WHERE active=1')->fetchColumn()];
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>RCCG Admin</title><style>body{font:15px/1.5 system-ui;background:#f6f8fb;color:#172033;margin:0}.wrap{max-width:1250px;margin:auto;padding:18px}.head{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.head h1{margin-right:auto}.nav{display:flex;gap:6px;overflow:auto;padding:8px 0 14px}.nav a{white-space:nowrap;text-decoration:none;padding:9px 12px;background:white;border:1px solid #dfe7f3;border-radius:10px}.nav a.on{background:#0a4dbf;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.card{background:white;border:1px solid #dfe7f3;border-radius:14px;padding:14px;margin:10px 0}.stat strong{font-size:28px;color:#062451}input,textarea,select,button{font:inherit;padding:10px;border:1px solid #cfd9e8;border-radius:9px;max-width:100%}input,textarea,select{width:100%}textarea{min-height:100px}button{font-weight:800;background:#0a4dbf;color:white;cursor:pointer}.danger{background:#fff;color:#b42318;border-color:#ffc9c4}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;border-bottom:1px solid #e4e9f1;padding:9px;vertical-align:top}table{display:block;overflow:auto}.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.muted{color:#667085}.flash{background:#ecfdf3;color:#027a48;padding:10px;border-radius:10px}.tiny{font-size:12px}.badge{padding:3px 7px;border-radius:999px;background:#eef5ff;color:#0a4dbf}</style></head><body><div class="wrap"><div class="head"><h1>RCCG Open Heavens Fife Admin</h1><a href="../" target="_blank">Open WebApp ↗</a><form method="post"><button name="logout" value="1" class="danger">Sign out</button></form></div><?php if($flash):?><p class="flash"><?=htmlspecialchars($flash)?></p><?php endif?><nav class="nav"><?php foreach(['dashboard'=>'Dashboard','settings'=>'Church Info','services'=>'Service Times','events'=>"What's On",'lessons'=>'Discovery Class Teacher Manual','worshippers'=>'First-Time Worshippers','donations'=>'Donation','messages'=>'Messages','subscribers'=>'Subscribers'] as $k=>$v):?><a class="<?=$tab===$k?'on':''?>" href="?tab=<?=$k?>"><?=$v?></a><?php endforeach?></nav>
