<?php elseif($tab==='settings'):?><h2>Church Information & Links</h2><?php foreach(['phone','address','website','facebook','youtube','zoom_url','donation_sort_code','donation_account_number'] as $k):?><form class="card" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="save_setting"><input type="hidden" name="key" value="<?=$k?>"><label><strong><?=htmlspecialchars($k)?></strong></label><input name="value" value="<?=htmlspecialchars($settings[$k]??'')?>"><button>Save</button></form><?php endforeach?>
<?php elseif($tab==='services'):?><h2>Service Times</h2><p class="muted">These display rows are stored in the private SQLite database outside public_html.</p><form class="card" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="add_service"><div class="row"><input name="sort_order" type="number" value="100" placeholder="Sort"><input name="day_label" required placeholder="Day"><input name="time_label" required placeholder="Time"><input name="service_name" required placeholder="Service name"></div><textarea name="note" placeholder="Optional note"></textarea><button>Add service time</button></form><table><tr><th>Day</th><th>Time</th><th>Service</th><th>Note</th><th></th></tr><?php foreach($DB->query('SELECT * FROM service_times ORDER BY sort_order,id') as $r):?><tr><td><?=htmlspecialchars($r['day_label'])?></td><td><?=htmlspecialchars($r['time_label'])?></td><td><?=htmlspecialchars($r['service_name'])?></td><td><?=htmlspecialchars($r['note'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="delete_service"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Delete</button></form></td></tr><?php endforeach?></table>
<h2 style="margin-top:28px">Recurring What's On / Quick Access Schedule</h2><p class="muted">These recurring rules are also stored in the private SQLite database. Editing them does not require rebuilding public_html. Weekdays use 1=Monday through 7=Sunday. Leave Join URL blank when the rule already uses a private setting such as the church Zoom link.</p>
