<?php elseif($tab==='lessons'):?><h2>Discovery Class Teacher Manual</h2><div class="card"><p>The Discovery Class Teacher Manual is now loaded from authorised JSON files in <code>rccg_fife_private/discovery_class/2026-2027/teacher/</code>, outside <code>public_html</code>.</p><p>Only authorised Discovery Class Teacher Manual content is published in v6.</p><p>Use the private deployment package to update lesson files; no public rebuild is required for lesson-content changes.</p></div>
<?php elseif($tab==='worshippers'):?><div class="head"><h2>First-Time Worshippers</h2><a href="?tab=worshippers&export=worshippers">Export CSV</a></div><p class="muted">These responses are stored separately from the mailing list.</p><table><tr><th>Date</th><th>Name</th><th>Contact</th><th>Rating</th><th>May contact?</th><th>Address</th><th>Prayer Point</th><th>Suggestion</th><th></th></tr><?php foreach($DB->query('SELECT * FROM first_time_worshippers ORDER BY id DESC LIMIT 1000') as $r):?><tr><td class="tiny"><?=htmlspecialchars($r['created_at'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['email'])?><br><?=htmlspecialchars($r['phone'])?></td><td><?=str_repeat('★',max(0,min(5,(int)$r['rating'])))?> <span class="tiny">(<?=((int)$r['rating'])?>/5)</span></td><td><?=$r['may_contact']?'Yes':'No'?></td><td><?=htmlspecialchars($r['address'])?></td><td><?=nl2br(htmlspecialchars($r['prayer_point']))?></td><td><?=nl2br(htmlspecialchars($r['suggestion']))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="delete_worshipper"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Delete</button></form></td></tr><?php endforeach?></table>
